                        routes[i], routes[j] = aa, b[:pos] + [c] + b[pos:]
                        changed = True
                        break
                if changed:
                    break

    routes = [r for r in routes if r]
    routes.sort(key=lambda r: (r[0], len(r), r))
    return routes
